const fs = require('fs');
const {
  Document, Packer, Paragraph, TextRun, Table, TableRow, TableCell,
  AlignmentType, LevelFormat, HeadingLevel, BorderStyle, WidthType,
  ShadingType, PageBreak
} = require('docx');

// Brand colors (luxe, feminine, premium feel)
const NAVY = "1A2E40";
const GOLD = "B89968";
const CREAM = "F5EFE6";
const SOFT_GRAY = "6B6B6B";
const LIGHT_DIVIDER = "D4C9B8";

// Reusable border for tables
const cellBorder = { style: BorderStyle.SINGLE, size: 4, color: LIGHT_DIVIDER };
const allBorders = { top: cellBorder, bottom: cellBorder, left: cellBorder, right: cellBorder };

// Helper: section heading divider
const goldDivider = () => new Paragraph({
  children: [new TextRun({ text: "", size: 2 })],
  border: {
    bottom: { style: BorderStyle.SINGLE, size: 12, color: GOLD, space: 4 }
  },
  spacing: { before: 60, after: 240 }
});

// Helper: standard body paragraph
const body = (text, opts = {}) => new Paragraph({
  spacing: { after: 160, line: 320 },
  alignment: opts.align || AlignmentType.LEFT,
  children: [new TextRun({ text, size: 22, color: "333333", font: "Calibri" })]
});

// Helper: bold lead-in + regular text
const leadBody = (lead, text) => new Paragraph({
  spacing: { after: 160, line: 320 },
  children: [
    new TextRun({ text: lead, bold: true, size: 22, color: NAVY, font: "Calibri" }),
    new TextRun({ text: text, size: 22, color: "333333", font: "Calibri" })
  ]
});

// Helper: bullet
const bullet = (text) => new Paragraph({
  numbering: { reference: "bullets", level: 0 },
  spacing: { after: 100, line: 300 },
  children: [new TextRun({ text, size: 22, color: "333333", font: "Calibri" })]
});

// Helper: bullet with bold lead
const bulletLead = (lead, text) => new Paragraph({
  numbering: { reference: "bullets", level: 0 },
  spacing: { after: 100, line: 300 },
  children: [
    new TextRun({ text: lead, bold: true, size: 22, color: NAVY, font: "Calibri" }),
    new TextRun({ text: text, size: 22, color: "333333", font: "Calibri" })
  ]
});

// Helper: H1 (section title)
const h1 = (text) => new Paragraph({
  heading: HeadingLevel.HEADING_1,
  spacing: { before: 360, after: 120 },
  children: [new TextRun({ text: text.toUpperCase(), bold: true, size: 30, color: NAVY, font: "Calibri", characterSpacing: 40 })]
});

// Helper: H2 (subsection)
const h2 = (text) => new Paragraph({
  heading: HeadingLevel.HEADING_2,
  spacing: { before: 240, after: 120 },
  children: [new TextRun({ text, bold: true, size: 26, color: NAVY, font: "Calibri" })]
});

// Helper: small caps eyebrow
const eyebrow = (text) => new Paragraph({
  spacing: { after: 80 },
  children: [new TextRun({ text: text.toUpperCase(), bold: true, size: 18, color: GOLD, font: "Calibri", characterSpacing: 80 })]
});

// Helper: shaded callout cell
const calloutBox = (titleText, bodyText) => new Table({
  width: { size: 9360, type: WidthType.DXA },
  columnWidths: [9360],
  rows: [
    new TableRow({
      children: [
        new TableCell({
          borders: {
            top: { style: BorderStyle.SINGLE, size: 4, color: GOLD },
            bottom: { style: BorderStyle.SINGLE, size: 4, color: GOLD },
            left: { style: BorderStyle.SINGLE, size: 4, color: GOLD },
            right: { style: BorderStyle.SINGLE, size: 4, color: GOLD }
          },
          width: { size: 9360, type: WidthType.DXA },
          shading: { fill: CREAM, type: ShadingType.CLEAR },
          margins: { top: 240, bottom: 240, left: 320, right: 320 },
          children: [
            new Paragraph({
              spacing: { after: 100 },
              children: [new TextRun({ text: titleText, bold: true, size: 24, color: NAVY, font: "Calibri" })]
            }),
            new Paragraph({
              spacing: { line: 300 },
              children: [new TextRun({ text: bodyText, size: 22, color: "333333", font: "Calibri", italics: true })]
            })
          ]
        })
      ]
    })
  ]
});

// Helper: two-column comparison row
const exchangeRow = (luxoraGives, micheleGives) => new TableRow({
  children: [
    new TableCell({
      borders: allBorders,
      width: { size: 4680, type: WidthType.DXA },
      shading: { fill: "FFFFFF", type: ShadingType.CLEAR },
      margins: { top: 160, bottom: 160, left: 200, right: 200 },
      children: [new Paragraph({
        spacing: { line: 280 },
        children: [new TextRun({ text: luxoraGives, size: 21, color: "333333", font: "Calibri" })]
      })]
    }),
    new TableCell({
      borders: allBorders,
      width: { size: 4680, type: WidthType.DXA },
      shading: { fill: "FFFFFF", type: ShadingType.CLEAR },
      margins: { top: 160, bottom: 160, left: 200, right: 200 },
      children: [new Paragraph({
        spacing: { line: 280 },
        children: [new TextRun({ text: micheleGives, size: 21, color: "333333", font: "Calibri" })]
      })]
    })
  ]
});

const exchangeHeader = () => new TableRow({
  tableHeader: true,
  children: [
    new TableCell({
      borders: allBorders,
      width: { size: 4680, type: WidthType.DXA },
      shading: { fill: NAVY, type: ShadingType.CLEAR },
      margins: { top: 200, bottom: 200, left: 200, right: 200 },
      children: [new Paragraph({
        children: [new TextRun({ text: "WHAT LUXORA OFFERS MICHELE", bold: true, size: 22, color: "FFFFFF", font: "Calibri", characterSpacing: 40 })]
      })]
    }),
    new TableCell({
      borders: allBorders,
      width: { size: 4680, type: WidthType.DXA },
      shading: { fill: NAVY, type: ShadingType.CLEAR },
      margins: { top: 200, bottom: 200, left: 200, right: 200 },
      children: [new Paragraph({
        children: [new TextRun({ text: "WHAT MICHELE OFFERS LUXORA", bold: true, size: 22, color: "FFFFFF", font: "Calibri", characterSpacing: 40 })]
      })]
    })
  ]
});

// Build the document
const children = [];

// ===== COVER =====
children.push(new Paragraph({ spacing: { before: 1200 }, children: [new TextRun("")] }));

children.push(new Paragraph({
  alignment: AlignmentType.CENTER,
  spacing: { after: 120 },
  children: [new TextRun({ text: "THE LUXORA COLLECTIVE", bold: true, size: 28, color: NAVY, font: "Calibri", characterSpacing: 120 })]
}));

children.push(new Paragraph({
  alignment: AlignmentType.CENTER,
  spacing: { after: 600 },
  children: [new TextRun({ text: "× MICHELE PELAFAS DESIGN", size: 24, color: GOLD, font: "Calibri", characterSpacing: 80 })]
}));

children.push(new Paragraph({
  alignment: AlignmentType.CENTER,
  border: { bottom: { style: BorderStyle.SINGLE, size: 12, color: GOLD, space: 8 } },
  spacing: { after: 400 },
  children: [new TextRun("")]
}));

children.push(new Paragraph({
  alignment: AlignmentType.CENTER,
  spacing: { after: 200 },
  children: [new TextRun({ text: "Strategic Partnership Proposal", bold: true, size: 44, color: NAVY, font: "Calibri" })]
}));

children.push(new Paragraph({
  alignment: AlignmentType.CENTER,
  spacing: { after: 600 },
  children: [new TextRun({ text: "A premium alliance for the medspa industry", italics: true, size: 24, color: SOFT_GRAY, font: "Calibri" })]
}));

children.push(new Paragraph({
  alignment: AlignmentType.CENTER,
  spacing: { after: 80 },
  children: [new TextRun({ text: "PREPARED FOR", bold: true, size: 18, color: GOLD, font: "Calibri", characterSpacing: 80 })]
}));

children.push(new Paragraph({
  alignment: AlignmentType.CENTER,
  spacing: { after: 320 },
  children: [new TextRun({ text: "Michele Pelafas, Founder, Michele Pelafas Inc.", size: 24, color: NAVY, font: "Calibri" })]
}));

children.push(new Paragraph({
  alignment: AlignmentType.CENTER,
  spacing: { after: 80 },
  children: [new TextRun({ text: "PREPARED BY", bold: true, size: 18, color: GOLD, font: "Calibri", characterSpacing: 80 })]
}));

children.push(new Paragraph({
  alignment: AlignmentType.CENTER,
  spacing: { after: 80 },
  children: [new TextRun({ text: "Bethany Anne, Co-Founder & CEO", size: 24, color: NAVY, font: "Calibri" })]
}));

children.push(new Paragraph({
  alignment: AlignmentType.CENTER,
  spacing: { after: 80 },
  children: [new TextRun({ text: "Eric, Co-Founder & CFO", size: 24, color: NAVY, font: "Calibri" })]
}));

children.push(new Paragraph({
  alignment: AlignmentType.CENTER,
  spacing: { after: 600 },
  children: [new TextRun({ text: "The Luxora Collective", italics: true, size: 22, color: SOFT_GRAY, font: "Calibri" })]
}));

children.push(new Paragraph({
  alignment: AlignmentType.CENTER,
  children: [new TextRun({ text: "theluxoracollective.co", size: 20, color: GOLD, font: "Calibri" })]
}));

children.push(new Paragraph({ children: [new PageBreak()] }));

// ===== OPENING NOTE =====
children.push(eyebrow("A Note Before We Begin"));
children.push(h1("Michele,"));
children.push(goldDivider());

children.push(body("After our conversation last week, I went straight back to Eric and said the same thing I told you on the call: you are the missing piece."));

children.push(body("For three years, I've been walking medspa owners through every layer of their business, sales, operations, KPIs, memberships, packages, marketing, AI, partnerships, and consistently hitting the same wall. The owner asks, \"What do you think of my space?\" and I give them an honest answer they aren't equipped to act on. I can tell them the room feels cold, the retail is positioned wrong, the lighting is killing the experience, but I'm not the one who can hand them a real plan to fix it."));

children.push(body("You are."));

children.push(body("What follows is everything I'd love to explore with you tomorrow. Some of it is what we already discussed. Some of it is new, including a service expansion we'd love your input on, designed specifically for the brand-new medspa owners we're starting to attract more often. None of this is locked in. It's a starting point for a real conversation about what a long-term alliance could look like between Luxora and Michele Pelafas Design."));

children.push(body("Talk soon,"));
children.push(new Paragraph({
  spacing: { before: 100, after: 80 },
  children: [new TextRun({ text: "Bethany Anne", bold: true, size: 22, color: NAVY, font: "Calibri" })]
}));
children.push(new Paragraph({
  children: [new TextRun({ text: "Co-Founder & CEO, The Luxora Collective", italics: true, size: 20, color: SOFT_GRAY, font: "Calibri" })]
}));

children.push(new Paragraph({ children: [new PageBreak()] }));

// ===== WHY THIS PARTNERSHIP =====
children.push(eyebrow("Section One"));
children.push(h1("Why This Alliance Makes Sense"));
children.push(goldDivider());

children.push(body("We sit on opposite ends of the same problem."));

children.push(body("Luxora walks into medspas generating $500K to $2M and finds the leaks: undertrained front desks, unconverted consults, weak memberships, no real package architecture, no partnership ecosystem, no KPI tracking. We plug those holes through our 90-Day Growth Engine and stay on as a long-term partner once the foundation is solid."));

children.push(body("Michele Pelafas Design walks into the same industry and creates the physical environment that makes premium pricing, premium positioning, and premium client retention possible in the first place. The space is the silent salesperson. When it's right, everything we install lands harder. When it's wrong, we're fighting the room."));

children.push(h2("The overlap"));

children.push(bulletLead("Identical target customer.", " Independent medspa owners, predominantly women, in the $500K to $3M range, who care about brand and experience."));
children.push(bulletLead("Complementary, not competing.", " You design the space. We design the systems that run inside it. Neither of us touches the other's lane."));
children.push(bulletLead("Shared philosophy.", " You said it best on our call: a tasteful, on-brand space is a direct reflection of the owner's talent and skill. That's exactly how I sell it to owners every day."));
children.push(bulletLead("Same volume model.", " Both businesses are built to scale, not to be boutique-priced gatekeepers. Mid-market accessibility is a strategic match."));

children.push(new Paragraph({ spacing: { before: 200 }, children: [new TextRun("")] }));
children.push(calloutBox(
  "The opening you mentioned",
  "You shared that you don't currently have a dedicated growth partner, and the majority of your clients fall into either startup or established multi-location categories. The middle, the $500K to $2M operators trying to grow into their next stage, is exactly where Luxora lives. That's the gap we want to fill for you."
));

children.push(new Paragraph({ children: [new PageBreak()] }));

// ===== THE NEW SERVICE EXPANSION =====
children.push(eyebrow("Section Two"));
children.push(h1("A New Service We Want Your Input On"));
children.push(goldDivider());

children.push(eyebrow("Brand-new Medspa Launch Track"));

children.push(body("On our call I mentioned we built our 90-Day Growth Engine around operators who already have three to six staff members and an existing client base. That's still our core. But after rebranding in October, we've been getting steady inbound from a different audience: brand-new medspa owners who haven't opened the doors yet, or who opened recently and are still figuring out what they don't know."));

children.push(body("Historically we've turned most of these conversations away or referred them out. After our call, Eric and I sat down and realized we've been leaving real revenue, and real impact, on the table. So we're scoping a Launch Track designed specifically for pre-opening and first-year operators. And the very first conversation we wanted to have about it was with you."));

children.push(h2("Why we'd love Michele Pelafas Design embedded as the design anchor"));

children.push(bulletLead("It's the single biggest mistake we see.", " Owners spend $300K+ on build-out before they understand their market, their service mix, their patient flow, or their brand. By the time they call us, the space is already working against them."));
children.push(bulletLead("Catching them earlier protects everyone.", " If we get to a brand-new owner before they sign a lease or finance 14 lasers, we can route them to you for the design conversation while we handle the business architecture. That's a clean win for the owner and a co-sourced deal for us."));
children.push(bulletLead("It positions you as the design authority from day one.", " Not the agency they hired after they realized their first attempt didn't work. Day one. Embedded in the playbook."));

children.push(h2("How it could work"));

children.push(bulletLead("The Launch Track itself.", " A pre-opening or first-year program covering market validation, service mix, pricing, brand positioning, vendor selection, hiring framework, KPI setup, and yes, design strategy."));
children.push(bulletLead("Your role.", " Featured design partner inside the Launch Track. Every brand-new owner who comes through Luxora gets a structured introduction to Michele Pelafas Design as the recommended design authority, with options ranging from full ground-up design to a strategic space analysis depending on their stage and budget."));
children.push(bulletLead("Our role.", " On your end, we become your dedicated growth partner for the $500K to $2M segment, plus the new Launch Track segment, filling the gap you mentioned you don't currently have covered."));
children.push(bulletLead("Pricing tier.", " Launch Track would be priced to be accessible for early-stage operators, similar to our current $9K, 90-day model. The goal is volume and long-term partnership, not a high-ticket gate."));

children.push(new Paragraph({ spacing: { before: 200 }, children: [new TextRun("")] }));
children.push(calloutBox(
  "What we'd love from you",
  "Honest feedback on the structure, your recommended price points and scopes for early-stage owners, and any guardrails you'd want in place for how we represent design in our materials. We'd rather build this with you than build it and ask you to plug into something that doesn't fit your business."
));

children.push(new Paragraph({ children: [new PageBreak()] }));

// ===== THE EXCHANGE =====
children.push(eyebrow("Section Three"));
children.push(h1("The Exchange"));
children.push(goldDivider());

children.push(body("Below is a side-by-side of what each of us brings to the table. Some of this is what we discussed on the call. Some is built on top of that conversation. All of it is a starting point we can shape together."));

children.push(new Paragraph({ spacing: { before: 200 }, children: [new TextRun("")] }));

children.push(new Table({
  width: { size: 9360, type: WidthType.DXA },
  columnWidths: [4680, 4680],
  rows: [
    exchangeHeader(),
    exchangeRow(
      "Featured design partner across all Luxora client onboarding, with Michele Pelafas Design positioned as the recommended authority on space, brand environment, and FF&E.",
      "Featured growth partner inside Michele Pelafas Design's referral ecosystem, filling the $500K to $2M segment you currently don't have covered."
    ),
    exchangeRow(
      "Embedded role in the new Launch Track for brand-new medspa owners. Direct access to pre-opening operators making major design decisions before they sign leases.",
      "Design strategy contribution to the Launch Track playbook, including recommended scopes and budget tiers for early-stage operators."
    ),
    exchangeRow(
      "Dedicated section on theluxoracollective.co featuring Michele Pelafas Design as our recommended design partner, with case study placement.",
      "Reciprocal placement on Michele Pelafas Design touchpoints positioning Luxora as the recommended growth partner for owners who need operational and revenue infrastructure."
    ),
    exchangeRow(
      "A custom-built Interior Design Playbook inside our 90-Day Growth Engine, co-authored with your input, walking owners through how to evaluate, brief, and engage a design partner. Yours by name throughout.",
      "Input on the playbook content and any design-strategy frameworks you want represented accurately to your standards."
    ),
    exchangeRow(
      "Podcast feature on The Aesthetic and Wellness Edge. Full episode dedicated to your work, your studio, your process, and your perspective on design as a revenue lever.",
      "Studio and manufacturing tour for our production crew, filmed as a multi-part content series featuring your in-house cabinetry, drapery, and upholstery operations."
    ),
    exchangeRow(
      "Cross-promotion across our blog, newsletter, social, and the upcoming workshop series. Two to three hour virtual workshops scoped for late 2026, with live events to follow.",
      "Cross-promotion to your existing client base and lead pipeline (approximately 13 booked calls per week). Warm introductions where Luxora is a fit for existing clients planning facelifts, renovations, or second locations."
    ),
    exchangeRow(
      "Confidential Experience Assessment access (the secret shopper service) for any of your existing clients who would benefit from an outside-eye operational audit.",
      "Space analysis, facelift, or full design consultation availability for Luxora clients flagged during our Revenue Leak Audits as having physical-environment issues holding back conversion."
    ),
    exchangeRow(
      "Introductions to our active partner ecosystem: stem cell banking (Acorn Biolabs and others), peptide and GLP-1 white-label providers, payment processing, partnership development specialists, and our strategic alliance with Aesthetic Injector Academy and Tracy Olson.",
      "Introductions to your established vendor and contractor network where relevant for our clients undertaking physical space changes."
    ),
    exchangeRow(
      "Co-branded content series: case studies on completed transformations, before-and-after stories that show the operational and design layers working together.",
      "Joint content collaboration including potential live event presence and joint workshop hosting once the partnership is established."
    )
  ]
}));

children.push(new Paragraph({ children: [new PageBreak()] }));

// ===== THE PROGRESSION =====
children.push(eyebrow("Section Four"));
children.push(h1("How We'd Like to Build This"));
children.push(goldDivider());

children.push(body("On our call, you mentioned you don't want to get married on the first date. Neither do we. Here's the runway we're proposing, with clear off-ramps at every stage."));

children.push(h2("Phase One: Affiliate Partnership (Months 1 to 3)"));
children.push(body("The lowest-commitment way to test the chemistry. We feature each other in our standard partnership rotation, exchange a small number of warm introductions, and see what the early signals look like. No exclusivity, no formal agreement beyond a referral arrangement."));

children.push(bulletLead("Concrete first moves: ", "Michele Pelafas Design featured on the Luxora partner page. Bethany books a podcast episode. We exchange three to five warm introductions in each direction to test fit."));

children.push(h2("Phase Two: Embedded Partnership (Months 4 to 9)"));
children.push(body("If Phase One delivers, we go deeper. Co-branded content, the Interior Design Playbook gets built and distributed, the Launch Track launches with Michele Pelafas Design as the design anchor. Reciprocal positioning becomes formal across both businesses."));

children.push(bulletLead("Concrete moves: ", "Studio tour content series filmed. Launch Track soft-launched with first cohort of brand-new owners. Joint workshop scoped and scheduled."));

children.push(h2("Phase Three: Strategic Alliance (Month 10 and beyond)"));
children.push(body("If the volume, the chemistry, and the results are there, we have the conversation about something more formal. That could look like primary growth-partner status for Luxora inside Michele Pelafas Design's network, primary design-partner status for Michele Pelafas Design inside Luxora's network, joint live events, or a deeper revenue-share structure. We'd build that conversation around real data, not assumptions."));

children.push(new Paragraph({ spacing: { before: 200 }, children: [new TextRun("")] }));
children.push(calloutBox(
  "Why this progression",
  "We have two existing growth partners who work exclusively with Luxora. Both started as Phase One affiliates. We don't believe in locking anyone in until the partnership has earned the right to be that close. The phased model protects both of us."
));

children.push(new Paragraph({ children: [new PageBreak()] }));

// ===== ABOUT LUXORA (CREDIBILITY) =====
children.push(eyebrow("Section Five"));
children.push(h1("About The Luxora Collective"));
children.push(goldDivider());

children.push(body("So you have everything you need in one place, here's the snapshot of who we are and what we install."));

children.push(h2("The model"));

children.push(body("We are a premium revenue growth partner for independent medspas generating $500K to $2M annually. Owners built their business to offer transformation, not manage spreadsheets. Luxora makes the business reflect that vision."));

children.push(body("We work from the inside out. We start with a Revenue Leak Audit, recovering revenue lost to undertrained front desks, unconverted consults, stagnant clients, missing memberships, and weak packages. Then we deliver a full Market Blueprint of their area before recommending any new investment. Once the foundation is solid, we install the right services at the right time: staff sales training, systems that run without the owner in every transaction, memberships, package architecture, AI follow-up, CRM, partnerships, reputation engine, marketing, and LTV frameworks."));

children.push(body("It's done-with-you, with knowledge transfer at every step. We prefer one-year-plus partnerships. The goal is for the owner to be more capable, more confident, and more in control, not dependent on us."));

children.push(h2("The team"));

children.push(bulletLead("Bethany Anne, Co-Founder & CEO. ", "Eighteen years in aesthetics. Started in 2007 in dermatology and plastics in Valencia, Beverly Hills, and Calabasas. Front desk, medical assisting, surgical tech, cosmetic sales, billing, then management of three locations, twelve surgeons, eight doctors, forty-four staff. Built three marketing agencies. Host of The Aesthetic and Wellness Edge podcast."));

children.push(bulletLead("Eric, Co-Founder & CFO. ", "Has bought, scaled, and sold multiple seven and eight-figure companies. CEO of operations with 600 to 700 employees. Brings the operational and acquisition rigor that lets us scale Luxora into the volume model it is today."));

children.push(bulletLead("Aanchal. ", "Executive assistant managing outreach and content coordination."));

children.push(bulletLead("Jacques. ", "Tech, media, and Meta ads."));

children.push(bulletLead("Keisha at Southern Social. ", "Organic content and social media."));

children.push(h2("The 90-Day Growth Engine offer"));

children.push(bulletLead("Investment: ", "$9,000 over three months. Intentionally affordable to enable scale during this growth phase."));
children.push(bulletLead("Guarantee: ", "We double the client's investment in new and recurring revenue, identified during the Revenue Leak Audit, within the engagement period."));
children.push(bulletLead("Structure: ", "Nine sequenced playbooks delivered over the 90 days. Bi-weekly check-ins. Embedded AI prompts. Knowledge transfer model where clients implement through their own staff with our frameworks."));
children.push(bulletLead("After 90 days: ", "Optional move into the inner circle for ongoing partnership at a low monthly retainer."));

children.push(h2("Strategic ecosystem"));

children.push(body("Active partnerships and alliances include Aesthetic Injector Academy (Tracy Olson), Acorn Biolabs (regenerative medicine and stem cell banking), peptide and GLP-1 white-label medical providers, an esthetics-focused payment processor, and select private equity contacts for clients ready to position for acquisition. We are actively building the design layer of this ecosystem, which is where you come in."));

children.push(new Paragraph({ children: [new PageBreak()] }));

// ===== NEXT STEPS =====
children.push(eyebrow("Section Six"));
children.push(h1("What We'd Love From Tomorrow's Call"));
children.push(goldDivider());

children.push(body("Tomorrow isn't about closing anything. It's about pressure-testing whether this fits both of our businesses honestly. Here's what we're hoping to walk away with:"));

children.push(bulletLead("Your reaction to the Launch Track concept. ", "Does the brand-new medspa segment make sense for you to be embedded in? What scopes and price points would you want represented? What would you want excluded?"));

children.push(bulletLead("Your honest take on Phase One. ", "Featured placement, podcast episode, three to five warm introductions in each direction. Comfortable starting point or do you want to scope it differently?"));

children.push(bulletLead("Calendar alignment. ", "When does it make sense to film the studio tour? When would Phase One officially go live? Who on each side is the point person?"));

children.push(bulletLead("Anything missing. ", "If there's a way to structure this that serves your business better, we want to hear it now, not three months from now."));

children.push(new Paragraph({ spacing: { before: 200 }, children: [new TextRun("")] }));
children.push(calloutBox(
  "One more thing",
  "On our call you said, \"I think we could really do some damage together.\" Eric and I quoted that to each other about six times this week. We're in. We just want to do it the right way, with the right structure, so that a year from now we're looking at real numbers and a real partnership, not a handshake that faded."
));

// ===== CLOSING =====
children.push(new Paragraph({ spacing: { before: 600 }, children: [new TextRun("")] }));

children.push(new Paragraph({
  alignment: AlignmentType.CENTER,
  border: { top: { style: BorderStyle.SINGLE, size: 12, color: GOLD, space: 8 } },
  spacing: { before: 400, after: 400 },
  children: [new TextRun("")]
}));

children.push(new Paragraph({
  alignment: AlignmentType.CENTER,
  spacing: { after: 200 },
  children: [new TextRun({ text: "Looking forward to tomorrow.", italics: true, size: 26, color: NAVY, font: "Calibri" })]
}));

children.push(new Paragraph({
  alignment: AlignmentType.CENTER,
  spacing: { after: 80 },
  children: [new TextRun({ text: "Bethany Anne & Eric", bold: true, size: 24, color: NAVY, font: "Calibri" })]
